    static final int MOD = 1_000_000_007;
    static List<Integer>[] tree;
    static long[][] dp;
    static long[] fact, invFact;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        tree = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) tree[i] = new ArrayList<>();
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 2; i <= N; i++) {
            int p = Integer.parseInt(st.nextToken());
            tree[p].add(i);
        }

        // Precompute factorials
        fact = new long[N + 1];
        invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i-1] * i % MOD;
        invFact[N] = modPow(fact[N], MOD - 2);
        for (int i = N - 1; i >= 0; i--) invFact[i] = invFact[i+1] * (i+1) % MOD;

        dp = new long[N + 1][];
        dfs(1);
        System.out.println(dp[1][0]);
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }

    static long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    static void dfs(int u) {
        dp[u] = new long[]{1}; // dp[u][0] = 1 for leaf
        int totalSize = 1;
        for (int v : tree[u]) {
            dfs(v);
            int szV = dp[v].length;
            long[] newDp = new long[totalSize + szV];
            // merge dp[u] and dp[v]
            for (int i = 0; i < dp[u].length; i++) {
                if (dp[u][i] == 0) continue;
                for (int j = 0; j < szV; j++) {
                    if (dp[v][j] == 0) continue;
                    // Merging: we have i bad edges from u's previous part, j from child v
                    // In child's arrangement, it has j bad edges with u (which are not yet placed)
                    // When merging, we place child's blocks into the gaps.
                    // Total elements from u so far: totalSize
                    // Child subtree size: szV
                    // Number of gaps = totalSize + 1 (before, between, after)
                    // We need to choose positions for child's szV elements.
                    // But we also need to consider bad adjacency formation:
                    // Child's block that touches u on either side creates bad edges.
                    // We consider splitting child's blocks into "free" blocks and those that create bad edges.
                    // Standard formula:
                    // Let a = totalSize, b = szV
                    // We want to insert b items into a+1 gaps.
                    // Some gaps may receive >0 items.
                    // For each existing bad edge from child (j), we need to place those touching u.
                    // Actually we use known combinatorial merging:
                    // We have j bad edges from child (meaning j adjacencies between u and child's blocks)
                    // When merging, the number of new bad edges formed is k (0 <= k <= j)
                    // because we can break some of those j connections.
                    // Number of ways: C(j, k) * C(a+1 - i, b - k) * C(i, j - k) ???
                    // Simpler: use known formula from editorial-like approach.
                    // We'll iterate over k = number of remaining bad edges from this child after merging.

                    for (int k = 0; k <= j && k <= totalSize + 1; k++) {
                        // We want exactly k bad edges kept from child's j.
                        // We have i previous bad edges from u.
                        // total gaps = totalSize + 1
                        // We need to place b items into gaps, with k of them placed adjacent to u.
                        // Gaps that are next to u: Each bad edge from u occupies a gap on one side.
                        // Actually simpler: Use standard formula from "tree permutation with adjacency constraints":
                        // ways = C(j, k) * C(totalSize + 1 - i, b - k) * C(i, j - k)
                        // Explanation: choose which k of child's bad edges survive
                        // then choose gaps that are not adjacent to u's bad edges for the remaining b-k blocks
                        // then place the j-k dissolved bad edges into gaps adjacent to u's bad edges.
                        long ways = comb(j, k) * comb(totalSize + 1 - i, b - k) % MOD
                                  * comb(i, j - k) % MOD;
                        ways = ways * dp[u][i] % MOD * dp[v][j] % MOD;
                        newDp[i + k] = (newDp[i + k] + ways) % MOD;
                    }
                }
            }
            totalSize += szV;
            dp[u] = newDp;
        }
    }
}

