import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    // NTT modulus: 998244353 = 119 * 2^23 + 1, primitive root = 3
    static final long MOD_NTT = 998244353L;
    static final long G = 3L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int[] parent = new int[N + 1];
        int[] deg = new int[N + 1];
        for (int i = 2; i <= N; i++) {
            parent[i] = fs.nextInt();
            deg[parent[i]]++;
            deg[i]++;
        }

        // Count connected induced subgraphs of size k in a tree:
        // any connected induced subgraph is a subtree.
        // Let c[k] = number of connected induced subgraphs with k vertices.
        // Answer = sum_k (-1)^k * c[k] * 2 * (N-k+1)!  for k>=1, plus N!
        // equivalently sum over matchings in edge-conflict graph by inclusion-exclusion on edge sets,
        // where any chosen edge set must form a forest and contributes 2^comp * (N-|V(S)|+comp)!.
        // In a tree, chosen edge set with c components and e edges has |V|=e+c, so term depends only on |V|.
        // Summing over forests by components transforms to connected-subgraph counts and gives:
        // ans = sum_{S connected, |S|=k} (-1)^(k-1) * 2 * (N-k+1)!  + N!
        // Thus:
        // ans = N! + sum_{k>=2} c[k] * (-1)^(k-1) * 2 * (N-k+1)!
        // and c[1]=N also fits if using factor 2*(N)! with sign +, so better use:
        // ans = sum_{k=0}^N a[k] * (N-k)! where a[0]=1 and
        // a[k] = sum_{t=1}^k (-1)^(k-t) 2^t * f[k][t], but this simplifies to:
        // For a tree, the independence polynomial of line graph equals matching polynomial of tree.
        // Number of valid permutations = sum_m (-1)^m M_m * 2^m * (N-m)!,
        // where M_m = number of matchings of size m in the tree.
        //
        // So compute matching counts M_m for the tree, then evaluate the sum.

        ArrayList<Integer>[] g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();
        for (int i = 2; i <= N; i++) {
            g[i].add(parent[i]);
            g[parent[i]].add(i);
        }

        int[] order = new int[N];
        int[] par = new int[N + 1];
        int[] st = new int[N];
        int top = 0, ordSz = 0;
        st[top++] = 1;
        par[1] = 0;
        while (top > 0) {
            int v = st[--top];
            order[ordSz++] = v;
            for (int to : g[v]) {
                if (to == par[v]) continue;
                par[to] = v;
                st[top++] = to;
            }
        }

        // DP:
        // dp0[v][k]: in subtree of v, matching size k, and v is unmatched to its children / parent edge not used from below.
        // dp1[v][k]: in subtree of v, matching size k, and v is matched to exactly one child.
        //
        // Start with {1} for dp0.
        // Merge children by convolution.
        // To attach child u:
        // new0 += dp0(v) * (dp0(u)+dp1(u))   // no edge v-u chosen
        // new1 += dp1(v) * (dp0(u)+dp1(u))   // already matched before
        // new1 += dp0(v) * shift( dp0(u) )   // choose edge v-u, so u must be free at root, +1 edge
        //
        // Final polynomial M = dp0[1] + dp1[1]

        long[][] dp0 = new long[N + 1][];
        long[][] dp1 = new long[N + 1][];
        int[] sz = new int[N + 1];

        for (int it = N - 1; it >= 0; it--) {
            int v = order[it];
            long[] cur0 = new long[]{1};
            long[] cur1 = new long[]{0};
            int curSize = 1;

            for (int u : g[v]) {
                if (u == par[v]) continue;
                long[] sumU = addPoly(dp0[u], dp1[u], MOD);

                long[] a = multiply(cur0, sumU);
                long[] b = multiply(cur1, sumU);
                long[] c = multiply(cur0, dp0[u]);
                c = shift1(c);

                int nlen = Math.max(a.length, Math.max(b.length, c.length));
                long[] nxt0 = new long[nlen];
                long[] nxt1 = new long[nlen];

                for (int i = 0; i < a.length; i++) nxt0[i] = (nxt0[i] + a[i]) % MOD;
                for (int i = 0; i < b.length; i++) nxt1[i] = (nxt1[i] + b[i]) % MOD;
                for (int i = 0; i < c.length; i++) {
                    nxt1[i] += c[i];
                    if (nxt1[i] >= MOD) nxt1[i] -= MOD;
                }

                cur0 = trim(nxt0);
                cur1 = trim(nxt1);
                curSize += sz[u];
            }

            dp0[v] = cur0;
            dp1[v] = cur1;
            sz[v] = curSize;
        }

        long[] match = addPoly(dp0[1], dp1[1], MOD);

        long[] fact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;

        long ans = 0;
        for (int m = 0; m < match.length; m++) {
            long term = match[m] * modPow(2, m, MOD) % MOD * fact[N - m] % MOD;
            if ((m & 1) == 0) {
                ans += term;
            } else {
                ans -= term;
            }
            ans %= MOD;
        }
        if (ans < 0) ans += MOD;
        System.out.println(ans);
    }

    static long[] trim(long[] a) {
        int n = a.length;
        while (n > 1 && a[n - 1] == 0) n--;
        return Arrays.copyOf(a, n);
    }

    static long[] shift1(long[] a) {
        long[] r = new long[a.length + 1];
        System.arraycopy(a, 0, r, 1, a.length);
        return r;
    }

    static long[] addPoly(long[] a, long[] b, long mod) {
        int n = Math.max(a.length, b.length);
        long[] r = new long[n];
        for (int i = 0; i < a.length; i++) r[i] = a[i];
        for (int i = 0; i < b.length; i++) {
            r[i] += b[i];
            if (r[i] >= mod) r[i] -= mod;
        }
        return trim(r);
    }

    static long modPow(long a, long e, long mod) {
        long r = 1 % mod;
        while (e > 0) {
            if ((e & 1) != 0) r = r * a % mod;
            a = a * a % mod;
            e >>= 1;
        }
        return r;
    }

    // Polynomial multiplication modulo 1e9+7 using NTT under 998244353 and coefficient splitting.
    static long[] multiply(long[] A, long[] B) {
        if (A.length == 0 || B.length == 0) return new long[0];
        int n = A.length, m = B.length;
        if ((long)n * m <= 4000) {
            long[] r = new long[n + m - 1];
            for (int i = 0; i < n; i++) {
                if (A[i] == 0) continue;
                for (int j = 0; j < m; j++) {
                    r[i + j] = (r[i + j] + A[i] * B[j]) % MOD;
                }
            }
            return trim(r);
        }

        int base = 1 << 15;
        long[] a0 = new long[n], a1 = new long[n];
        long[] b0 = new long[m], b1 = new long[m];
        for (int i = 0; i < n; i++) {
            a0[i] = A[i] & (base - 1);
            a1[i] = A[i] >> 15;
        }
        for (int i = 0; i < m; i++) {
            b0[i] = B[i] & (base - 1);
            b1[i] = B[i] >> 15;
        }

        long[] c00 = convolutionNTT(a0, b0);
        long[] c01 = convolutionNTT(a0, b1);
        long[] c10 = convolutionNTT(a1, b0);
        long[] c11 = convolutionNTT(a1, b1);

        int len = n + m - 1;
        long[] res = new long[len];
        long baseMod = base % MOD;
        long base2Mod = baseMod * baseMod % MOD;
        for (int i = 0; i < len; i++) {
            long v = 0;
            v = (v + (i < c00.length ? c00[i] : 0)) % MOD;
            long mid = 0;
            if (i < c01.length) mid += c01[i];
            if (i < c10.length) mid += c10[i];
            mid %= MOD;
            v = (v + mid * baseMod) % MOD;
            if (i < c11.length) v = (v + c11[i] % MOD * base2Mod) % MOD;
            res[i] = v;
        }
        return trim(res);
    }

    static long[] convolutionNTT(long[] a, long[] b) {
        int need = a.length + b.length - 1;
        int n = 1;
        while (n < need) n <<= 1;
        long[] fa = new long[n];
        long[] fb = new long[n];
        System.arraycopy(a, 0, fa, 0, a.length);
        System.arraycopy(b, 0, fb, 0, b.length);

        ntt(fa, false);
        ntt(fb, false);
        for (int i = 0; i < n; i++) fa[i] = fa[i] * fb[i] % MOD_NTT;
        ntt(fa, true);

        return Arrays.copyOf(fa, need);
    }

    static void ntt(long[] a, boolean invert) {
        int n = a.length;

        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; (j & bit) != 0; bit >>= 1) j ^= bit;
            j ^= bit;
            if (i < j) {
                long tmp = a[i];
                a[i] = a[j];
                a[j] = tmp;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            long wlen = modPow(G, (MOD_NTT - 1) / len, MOD_NTT);
            if (invert) wlen = modPow(wlen, MOD_NTT - 2, MOD_NTT);
            for (int i = 0; i < n; i += len) {
                long w = 1;
                int half = len >> 1;
                for (int j = 0; j < half; j++) {
                    long u = a[i + j];
                    long v = a[i + j + half] * w % MOD_NTT;
                    a[i + j] = u + v;
                    if (a[i + j] >= MOD_NTT) a[i + j] -= MOD_NTT;
                    a[i + j + half] = u - v;
                    if (a[i + j + half] < 0) a[i + j + half] += MOD_NTT;
                    w = w * wlen % MOD_NTT;
                }
            }
        }

        if (invert) {
            long invN = modPow(n, MOD_NTT - 2, MOD_NTT);
            for (int i = 0; i < n; i++) a[i] = a[i] * invN % MOD_NTT;
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

