    vector<vector<int64>> dp2(N);
    vector<int> sz(N);

    function<void(int)> dfs2 = [&](int u) {
        dp2[u] = {1};
        sz[u] = 1;
        for (int v : children[u]) {
            dfs2(v);
            int a_max = (int)dp2[u].size() - 1;
            int b_max = (int)dp2[v].size() - 1;
            vector<int64> ndp(a_max + b_max + 2, 0);
            for (int a = 0; a <= a_max; a++) {
