                    // So count_adj = 2 * C(sz[u] + sz[v] - 2, sz[v] - 1).
                    int64 comb_adj = 2 * nCr(sz[u] + sz[v] - 2, sz[v] - 1) % MOD;
                    int64 comb_not_adj = (comb - comb_adj + MOD) % MOD;

