    // after processing children, choosing exactly k selected child-edges (k<=2-t),
    // total selected edges in descendants + chosen child-edges = e,
    // total completed components inside processed part excluding any open one through u = c.
    //
    // Compress k dimension and store vector by (e,c).

    using Poly = vector<vector<long long>>; // [edges][components]

    auto add_poly = [&](Poly &A, int e, int c, long long val) {
        if (e >= (int)A.size()) A.resize(e + 1);
        if (c >= (int)A[e].size()) A[e].resize(c + 1, 0);
        A[e][c] = (A[e][c] + val) % MOD;
