                // Option 2: selected -> use dp[v][1], plus this edge contributes +1 edge
                for (int k = 0; k <= 2; k++) {
                    for (int e1 = 0; e1 < (int)cur[k].size(); e1++) {
                        for (int c1 = 0; c1 < (int)cur[k][e1].size(); c1++) {
                            long long val1 = cur[k][e1][c1];
                            if (!val1) continue;

                            // not select
                            for (int e2 = 0; e2 < (int)dp[v][0].size(); e2++) {
                                for (int c2 = 0; c2 < (int)dp[v][0][e2].size(); c2++) {
                                    long long val2 = dp[v][0][e2][c2];
                                    if (!val2) continue;
                                    add_poly(nxt[k], e1 + e2, c1 + c2, val1 * val2 % MOD);
                                }
