                            if (k + 1 + t <= 2) {
                                for (int e2 = 0; e2 < (int)dp[v][1].size(); e2++) {
                                    for (int c2 = 0; c2 < (int)dp[v][1][e2].size(); c2++) {
                                        long long val2 = dp[v][1][e2][c2];
                                        if (!val2) continue;
                                        add_poly(nxt[k + 1], e1 + e2 + 1, c1 + c2, val1 * val2 % MOD);
