            //   k=2 impossible because degree 3
            Poly res;
            for (int k = 0; k <= 2; k++) {
                for (int e = 0; e < (int)cur[k].size(); e++) {
                    for (int c = 0; c < (int)cur[k][e].size(); c++) {
                        long long val = cur[k][e][c];
                        if (!val) continue;
                        int nc = c;
                        if (t == 0 && k > 0) nc++;
                        add_poly(res, e, nc, val);
                    }
                }
            }
            dp[u][t] = move(res);
        }
    };

    dfs(1);

    long long ans = 0;
    // Root has no parent edge, so use t=0.
    for (int m = 0; m < (int)dp[1][0].size(); m++) {
        for (int c = 0; c < (int)dp[1][0][m].size(); c++) {
            long long waysSubsets = dp[1][0][m][c];
            if (!waysSubsets) continue;
            long long contrib = waysSubsets * fact[N - m] % MOD;
            contrib = contrib * ((c >= 63) ? 0 : 1) % MOD; // placeholder, replaced below
        }
    }

    vector<long long> pow2(N + 1, 1);
    for (int i = 1; i <= N; i++) pow2[i] = pow2[i - 1] * 2 % MOD;

    for (int m = 0; m < (int)dp[1][0].size(); m++) {
        for (int c = 0; c < (int)dp[1][0][m].size(); c++) {
            long long waysSubsets = dp[1][0][m][c];
            if (!waysSubsets) continue;
            long long contrib = waysSubsets * fact[N - m] % MOD * pow2[c] % MOD;
            if (m & 1) ans = (ans - contrib + MOD) % MOD;
            else ans = (ans + contrib) % MOD;
        }
    }

    cout << ans % MOD << '\n';
    return 0;
}

